def _text_to_category(apps, schema_editor):
    """Turn every distinct free-text supplier_category into a SupplierCategory
    row and point the supplier at it. Matching is case-insensitive so
    "Canned Goods" and "canned goods" collapse into one category; the first
    spelling seen wins."""
    SupplierProfile = apps.get_model('accounts', 'SupplierProfile')
    SupplierCategory = apps.get_model('accounts', 'SupplierCategory')
    by_key = {}
    for profile in SupplierProfile.objects.exclude(supplier_category=''):
        text = profile.supplier_category.strip()
        if not text:
            continue
        key = text.casefold()
        category = by_key.get(key)
        if category is None:
            category = SupplierCategory.objects.filter(name__iexact=text).first()
            if category is None:
                category = SupplierCategory.objects.create(name=text[:100])
            by_key[key] = category
        profile.category = category
        profile.save(update_fields=['category'])


def _category_to_text(apps, schema_editor):
    SupplierProfile = apps.get_model('accounts', 'SupplierProfile')
    for profile in SupplierProfile.objects.exclude(category=None).select_related('category'):
        profile.supplier_category = profile.category.name
        profile.save(update_fields=['supplier_category'])


